use strict;
use warnings;
use feature 'say';
sub add {
    my ($x, $y) = @_;
    return $x + $y;
}
my $sum = add(3, 4);
say $sum;
say add(10, 20);

use strict;
use warnings;
use feature 'say';
sub show {
    my $count = @_;
    my ($name) = @_;
    say "$count / $name";
}
show("Ada");

use strict;
use warnings;
use feature 'say';
sub sign {
    my ($n) = @_;
    return "negative" if $n < 0;
    return "zero" if $n == 0;
    return "positive";
}
say sign(-5);
say sign(0);
say sign(8);

use strict;
use warnings;
use feature 'say';
sub total {
    my $sum = 0;
    foreach my $n (@_) {
        $sum += $n;
    }
    return $sum;
}
my @prices = (3, 4, 5);
say total(@prices);
say total(1, 2);

use strict;
use warnings;
use feature 'say';
sub min_max {
    my @sorted = sort { $a <=> $b } @_;
    return ($sorted[0], $sorted[-1]);
}
my ($low, $high) = min_max(7, 2, 9, 4);
say "Low: $low, High: $high";

